select * from customer limit 20

--what is the total revenue generated by male versus female customers

select gender,SUM(purchase_amount) as revenue from customer group by gender

--Which customers used a discount but still spent more than the average purchase amount

select customer_id, purchase_amount from customer where discount_applied = 'Yes' and purchase_amount >= (select avg(purchase_amount) from customer)

--- Which are the top five products with the highest average review rating

select item_purchased, ROUND(AVG(review_rating::numeric),2) as "Average Review Rating" from customer
group by item_purchased order by avg(review_rating) desc limit 5

---- Compare the average purchase amounts between standard and express shipping

select shipping_type , avg(purchase_amount) as "Average Purchase amount" from customer where shipping_type in ('Standard','Express')group by shipping_type

----- Do subscribe customers spend more Compare average spend and total revenue between subscribers and non subscribers

select count('cusotomer_id') as "Total Cusotmer" ,round(avg(purchase_amount),2) as "Average",round(sum(purchase_amount),2) as "Total revenue", subscription_status from customer group by subscription_status 

----- Which five products have the highest percentage of purchases with discount applied

select item_purchased, Round(100 * sum(case when discount_applied = 'Yes' Then 1 Else 0 End)/Count(*),2) as discount_rate
from customer group by item_purchased
order by discount_rate desc
limit 5;

----- Segment customers into new returning and loyal based on their total number of previous purchases and show the count of each segment
with customer_type as(
select customer_id, previous_purchases,
Case 
     When previous_purchases = 1 Then 'New'
	 When previous_purchases Between 2 And 10 Then 'Returning'
	 ELSE 'Loyal'
	 END As customer_segment
from customer
)

select customer_segment, count(*) as "Number of Customers"
from customer_type
group by customer_segment

--- What are the top three most purchased products within each category

with item_counts as (
select category,
item_purchased,
count(customer_id) as total_orders,
ROW_NUMBER() over(partition by category order by count(customer_id)DESC) as item_rank
from customer
group by category, item_purchased
)

select item_rank, category , item_purchased , total_orders
from item_counts
where item_rank <=3

----------- Are customers who are repeat buyers more than five previous purchases also likely to subscribe
select subscription_status ,count(customer_id) as "Buyers" 
from customer where previous_purchases>5 group by subscription_status

----------- What is the revenue contribution of each age group?
select age_group , sum(purchase_amount) as total_revenue from customer group by age_group